import urllib.request, io, sys, subprocess

urls = {
  "doerr_memmingen": "https://www.econstor.eu/bitstream/10419/224973/1/How-new-airport-infrastructure-promotes-tourism.pdf",
  "eca_sr21_2014": "https://www.eca.europa.eu/lists/ecadocuments/insr14_21/insr14_21_en.pdf",
  "bitre_employment": "https://www.bitre.gov.au/sites/default/files/is_046.pdf",
  "mukkala_tervo": "https://www.regionalstudies.org/wp-content/uploads/2018/07/mukkala-tervo.pdf",
  "knock_rap": "https://assets.gov.ie/static/documents/rap-submission-ireland-west-airport.pdf",
  "itf_remote": "https://www.itf-oecd.org/sites/default/files/docs/dp201113.pdf",
}

def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (research)"})
    with urllib.request.urlopen(req, timeout=60) as r:
        return r.read()

pdfs = {}
for name, url in urls.items():
    try:
        data = fetch(url)
        pdfs[name] = data
        print(f"{name}: downloaded {len(data):,} bytes")
    except Exception as e:
        print(f"{name}: FAILED - {e}")

# install pypdf if needed
try:
    import pypdf
    print("pypdf available")
except ImportError:
    r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "pypdf"], capture_output=True, text=True)
    print("pip install rc:", r.returncode, r.stderr[:200])
    import pypdf

texts = {}
for name, data in pdfs.items():
    try:
        reader = pypdf.PdfReader(io.BytesIO(data))
        t = "\n".join((p.extract_text() or "") for p in reader.pages)
        texts[name] = t
        print(f"{name}: extracted {len(t):,} chars from {len(reader.pages)} pages")
    except Exception as e:
        print(f"{name}: extraction FAILED - {e}")
"}

