    up = json.loads(fetch("https://api.unpaywall.org/v2/10.1080/00343404.2020.1714022?email=research@example.org"))
    print("Unpaywall OA locations:")
    for loc in (up.get("oa_locations") or [])[:6]:
        print("  -", loc.get("url_for_pdf") or loc.get("url"))
except Exception as e:
    print("unpaywall failed:", e)

# 2) Try CESifo working paper 8010
