import urllib.request, json, io, pypdf

def fetch(url, timeout=60):
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()

# 1) BITRE - try different archive snapshots
for snap in ["2020", "2019", "2024", "2016"]:
    url = f"https://web.archive.org/web/{snap}id_/https://www.bitre.gov.au/sites/default/files/is_046.pdf"
    try:
        d = fetch(url, timeout=45)
        print(f"bitre {snap}: {len(d):,} bytes")
        if d[:4] == b"%PDF":
            try:
                reader = pypdf.PdfReader(io.BytesIO(d))
                t = "\n".join((p.extract_text() or "") for p in reader.pages)
                texts["bitre_employment"] = t
                print(f"  -> OK: {len(t):,} chars, {len(reader.pages)} pages")
                break
            except Exception as e:
                print("  -> parse failed:", e)
    except Exception as e:
        print(f"bitre {snap}: FAILED {type(e).__name__}")

# 2) ITF remote regions paper
try:
    d = fetch("https://www.itf-oecd.org/sites/default/files/docs/dp201113.pdf", timeout=45)
    print("itf:", len(d), "bytes")
    if d[:4] == b"%PDF":
        pdfs["itf_remote"] = d
        reader = pypdf.PdfReader(io.BytesIO(d))
        t = "\n".join((p.extract_text() or "") for p in reader.pages)
        texts["itf_remote"] = t
        print(f"itf: {len(t):,} chars, {len(reader.pages)} pages")
except Exception as e:
    print("itf FAILED:", type(e).__name__, e)

# 3) Unpaywall for Pauwels and Pot&Koster
for name, doi in [("pauwels2025", "10.1016/j.jairtraman.2025.102854"), ("potkoster2022", "10.1016/j.jtrangeo.2021.103262")]:
