    html = fetch("https://en.wikipedia.org/wiki/Tri-Cities_Airport_(Tennessee)").decode("utf-8", "replace")
    idx = html.find("stat1_header")
    seg = re.sub(r"<[^>]+>", " ", html[idx-50:idx+500])
    print("TRI infobox:", re.sub(r"\s+", " ", seg)[:400])
except Exception as e:
    print("TRI failed:", type(e).__name__, e)

# Fu et al. 2021 NZ paper
